("fecl3test","Neutral ferric chloride test solution","FeCl3","aq","pale-yellow",{"note":"violet with phenols, red with carboxylates, buff/brown with enols - the functional-group bottle for organic analysis"}),
("sodalime","Soda lime (NaOH + CaO)","mix","s","white-grey",{"note":"the CO2 absorbent in a respiration experiment and in the closed-loop rebreather; and the decarboxylating mixture that turns sodium acetate into methane"}),
("asbestossim","Filter paper (quantitative)","cellulose","s","white",{"note":"ashless - so a precipitate can be ignited with the paper; blue litmus, red litmus, starch-iodide, lead acetate and pH paper are all here as 'paper' objects with colours"}),
("c2h5ona","Sodium ethoxide","C2H5Na","s","white-grey",{"reacts":"vigorous","cas":"141-32-2","danger":3,"note":"made in the sim only as a solution in ethanol; with water it goes back to NaOH + ethanol with a hiss - the 'strongest base you can have in alcohol'"}),
("nah","Sodium hydride","NaH","s","grey-white",{"mp":425.0,"reacts":"vigorous","role":"reducer","cas":"7646-69-7","danger":3,"note":"with water: NaH -> NaOH + H2, and it ignites; the 'H- as a base' teaching point, kept display-only"}),
("lic1aq","Lithium chloride hydrate","LiCl","s","white",{"mp":605.0,"den":2.07,"sol":83.5,"ion":"Li+","hygro":True,"cas":"7447-41-8","danger":1,"note":"carmine-red flame; LiCl is covalent enough to dissolve in alcohol and acetone while the other alkali chlorides do not - the anomalous first member of group 1"}),
("rbcl","Rubidium chloride","RbCl","s","white",{"mp":715.0,"den":2.80,"sol":77.3,"ion":"Rb+","flame":"red-violet","cas":"7787-18-0","danger":1}),
