("srno3","Strontium nitrate","Sr(NO3)2","s","white",{"mp":570.0,"den":3.405,"sol":56.7,"ion":"Sr2+","flame":"crimson","cas":"10042-76-5","danger":2,"note":"the crimson fireworks red; and the nitrate whose decomposition gives SrO + NO2 + O2"}),
("cuno3solid","Copper(II) nitrate (solid) see cuno3a","x","s","blue",{}),
