("cuso4ammonia","Schweizer's reagent (tetraamminecopper(II))","Cu(NH3)4","aq","deep-blue",{"note":"[Cu(NH3)4](OH)2 - dissolves cellulose (cotton) to a clear deep-blue solution (cuprammonium rayon); a rare 'copper dissolves paper' demo"}),
("h2ptcl6","Chloroplatinic acid (platinic chloride)","H2PtCl6","aq","orange-yellow",{"note":"the yellow PtCl6^2- precipitates of K+, NH4+, Rb+ - the classic 'K+ and NH4+ are hard to tell apart' problem, solved by solubility of the hexachloroplatinates"}),
("na2hpo4","Disodium hydrogen phosphate","Na2HPO4","s","white",{"mp":34.6,"sol":125.4,"role":"ampho","cas":"7558-79-4","danger":0,"note":"Na2HPO4.12H2O 358.14, pH about 9; one half of the phosphate buffer pair and the MgNH4PO4 reagent partner"}),
("nah2po4","Sodium dihydrogen phosphate","NaH2PO4","s","white",{"den":2.04,"sol":77.0,"role":"acid","cas":"7558-80-7","danger":0,"note":"monobasic sodium phosphate pH about 4.5; NaH2PO4 + Na2HPO4 is a textbook buffer at pH 7.2"}),
("na3po4","Trisodium phosphate dodecahydrate","Na3PO4","s","white",{"den":1.62,"sol":21.2,"role":"base","cas":"7601-54-9","danger":2,"note":"Na3PO4.12H2O 380.12; strongly alkaline (pH about 12.5 at 0.1 M) - the 'sodium phosphate is a soap-maker's alkali' and the YBCO superconductor synthesis precursor"}),
