("naoh_soda","Caustic soda solution (50 %)","NaOH","aq","colourless",{"stock":{"conc_pct":50.0,"den":1.53,"molarity":19.1},"note":"saturated NaOH; on standing it crusts with Na2CO3 from the air, which is why the carbonate-free solution needs Ba(OH)2 treatment before a precise titration"}),
("limewater","Lime water (saturated Ca(OH)2)","Ca(OH)2","aq","colourless-opalescent",{"note":"the CO2 test: milky CaCO3, and the milkiness DISSOLVES again on excess CO2 as soluble Ca(HCO3)2 - both directions are exam questions, so the sim runs both"}),
("baoh2water","Baryta water (Ba(OH)2 solution)","Ba(OH)2","aq","colourless",{"note":"more sensitive than lime water for CO2 (lower Ksp of BaCO3), and the classic endothermic-freezing beaker partner with NH4Cl or NH4SCN"}),
("na2hco3aq","Sodium hydrogen carbonate solution","NaHCO3","aq","colourless",{"note":"pH about 8.3; the effervescence test for a carboxylic acid (RCOOH + HCO3- -> CO2) and the 'antacid' bottle in the medicine-cupboard lesson"}),
("aq_ammonia_cuso4","Deep-blue copper-ammonia solution","Cu(NH3)4SO4","aq","royal-blue",{"note":"excess NH3 into CuSO4: pale blue precipitate first (basic salt) then the deep-blue complex - 'two additions, opposite results'"}),
("hclgas_water","Hydrochloric acid gas in water (fuming)","HCl","aq","colourless",{"note":"one volume of water dissolves about 500 volumes of HCl at 0 C - the fountain demonstration where the flask collapses in seconds"}),
("nh4scn","Ammonium thiocyanate","NH4SCN","s","white",{"sol":170.0,"cas":"1762-95-4","danger":1,"note":"blood-red FeSCN2+ with Fe3+ - the equilibrium/Le Chatelier demo (add F- or oxalate and the colour vanishes) and the Volhard back-titration indicator"}),
("k4fe_cn6","Potassium ferrocyanide (solid) see k4fecn6","x","s","yellow",{}),
("h2s_gen","Hydrogen sulphide generator (FeS + dilute H2SO4)","mix","aq","colourless",{"note":"the apparatus entry, not a reagent: Kipp's or a Woulff bottle, with a lead-acetate-soaked guard; the sim requires the fume-hood flag before it runs"}),
("agno3alco","Silver nitrate in ethanol","AgNO3","aq-alc","colourless",{"note":"the alcoholic AgNO3 test that ranks alkyl halides by how fast AgX drops out: tertiary > secondary > primary, iodide > bromide > chloride - SN1 in one tube"}),
("cuoh2glyc","Copper(II) glycerate solution","Cu(C3H5O3)2","aq","deep-blue-transparent",{"note":"Cu(OH)2 dissolving in glycerol/polyol - the 'polyhydric alcohol' test, and why glycerol feels slippery like a base"}),
("sio4","Silicate gel plug","H2SiO3","s","white-gel",{"note":"used in the chemical-garden and water-glass hardening demos"}),
("feoh3gel","Iron(III) hydroxide gel (newly precipitated)","Fe(OH)3","s","brown-gel",{"note":"adsorbs dye and phosphate: the 'iodine flask wash' and the 'dyeing with mordant' lesson"}),
