("naalo2","Sodium aluminate","NaAlO2","s","white",{"sol":"hydrolyses","cas":"11092-32-3","danger":2,"note":"dissolving aluminium foil in NaOH gives this plus H2; add CO2 or acetic acid and Al(OH)3 flocks out - amphoteric in both directions"}),
("nacn_free_note","(Cyanide salts - not included)","x","s","",{"note":"deliberately excluded from the purchasable shelf: anhydrous HCN/alkali cyanides are lethal in minutes and have no place in a home app. The sim describes the hazard and the industrial chemistry (Andrussow, cyanidation of gold) without giving a bottle."}),
("kcn_note","(Potassium cyanide - reference/hazard only)","KCN","s","white",{"mp":634.0,"den":1.52,"sol":71.6,"cas":"151-50-8","danger":3,"note":"reference entry with lethal-dose and hydrolysis chemistry; locked in the sim, since 'add KCN' is exactly the click a responsible app must not allow"}),
("halite","Rock salt (natural halite, purple-grey)","NaCl","s","grey-pink",{"cas":"7647-14-5","note":"the mineral, with the same chemistry and a visible impurity colour - useful for the 'why pure crystals form' lesson"}),
("nh3gas_dry","Ammonia gas (dry)","NH3","g","colourless",{"mp":-77.7,"bp":-33.34,"den":0.00073,"sol":90.0,"role":"base","odour":"pungent alkaline","cas":"7664-41-7","danger":2,"note":"1 volume of water dissolves about 700 volumes - the blue fountain; lighter-than-air so it escapes upward; turns damp red litmus blue"}),
("co2","Carbon dioxide","CO2","g","colourless",{"mp":-78.5,"bp":-56.6,"den":0.00198,"sol":0.169,"role":"acid-oxide","cas":"124-38-9","danger":1,"note":"dense (1.5x air) so it pours down and puts out a candle; dry ice sublimes at -78.5 C; the 'gas that relights nothing, clouds limewater, and makes a candle-in-beaker experiment work'"}),
("o2","Oxygen","O2","g","colourless",{"mp":-218.8,"bp":-183.0,"den":0.00143,"sol":0.0043,"role":"oxidiser","cas":"7782-44-7","danger":1,"note":"relights a glowing splint; paramagnetic - a stream between the poles of a strong magnet is deflected; and '1 volume water dissolves 3 mL' is why fish need aerated water at 30 C"}),
("h2gas","Hydrogen","H2","g","colourless",{"mp":-259.1,"bp":-252.9,"den":0.0000899,"sol":0.00017,"role":"reducer","cas":"1333-74-0","danger":2,"note":"the squeaky pop (with a 'pop' that is actually a small detonation); lightest gas, diffuses fastest, and Zn + dilute H2SO4 is the generator; explosive 4-75 % in air - the sim always says 'test purity first'"}),
("n2gas","Nitrogen","N2","g","colourless",{"mp":-210.0,"bp":-195.8,"den":0.00125,"sol":0.0019,"cas":"7727-37-9","danger":0,"note":"inert at lab T because of the 945 kJ/mol triple bond; from NH4NO2 in solution, or by burning air over heated copper (which takes the O2 out)"}),
("cl2","Chlorine","Cl2","g","green-yellow",{"mp":-101.5,"bp":-34.04,"den":0.00321,"sol":0.71,"role":"oxidiser","odour":"pungent, choking, pool-like","cas":"7782-50-5","danger":3,"note":"bleaches dry litmus only in the presence of moisture, and it is toxic at 30 ppm; the sim allows only micro-scale generation behind the fume-hood gate"}),
