("no","Nitric oxide","NO","g","colourless",{"mp":-163.6,"bp":-151.8,"den":0.00134,"cas":"10102-43-9","danger":2,"note":"colourless at the mouth of the tube then brown fumes in air (2 NO + O2 -> 2 NO2) - so it MUST be collected over water, and that is the whole exam point; the signalling molecule that won a Nobel prize"}),
("n2o","Dinitrogen monoxide (laughing gas)","N2O","g","colourless",{"mp":-90.8,"bp":-88.5,"den":0.00198,"cas":"10024-97-2","danger":2,"note":"from NH4NO3 at 240-270 C (not hotter - it detonates); a glowing splint relights as well as in O2 because it decomposes back to N2 + O2"}),
("hcl_gas","Hydrogen chloride","HCl","g","colourless",{"mp":-114.2,"bp":-85.05,"den":0.00164,"sol":82.3,"role":"acid","odour":"pungent, fuming","cas":"7647-01-0","danger":2,"note":"from NaCl + concentrated H2SO4 (NOT with KBr/KI - they'd be oxidised); dense white fumes with NH3, and water rushes up the tube"}),
("h2s","Hydrogen sulphide","H2S","g","colourless",{"mp":-85.5,"bp":-60.3,"den":0.00154,"sol":4.0,"role":"reducer","odour":"rotten eggs - then paralyzes the nerve so you stop smelling it","cas":"7783-06-4","danger":3,"note":"anosmia at high concentration means 'I can't smell it any more' is the DANGER signal, not the all-clear; burns with a blue flame and 2 H2S + 3 O2 -> 2 SO2 + 2 H2O; lead acetate paper turns black"}),
