("sih4_ref","Silane","SiH4","g","colourless",{"mp":-185.1,"bp":-111.9,"den":0.00144,"cas":"7803-62-5","danger":3,"note":"pyrophoric; the semiconductor-CVD precursor (and a real industrial hazard story)"}),
("h2sfire","(reference) Water-gas / syngas","CO+H2","g","colourless",{"note":"C + H2O(steam) -> CO + H2, and CO + H2O -> CO2 + H2 (the water-gas shift) - the hydrogen-economy and catalyst-poisoning lesson"}),
("ozone","Ozone","O3","g","pale-blue",{"mp":-192.2,"bp":-112.0,"den":0.00214,"role":"oxidiser","odour":"sharp after a spark/storm","cas":"10028-15-6","danger":3,"note":"from a silent electric discharge; blackens starch-iodide paper, and 'O3 + I- -> O2 + IO3-' is why ozone meters are iodometric; absorbs UV (the ozone-hole chapter)"}),
